package com.minebench.scene;

/**
 * Builds the canonical evidence contract for terrain generated by the published suite seed.
 */
public final class SceneGenerator {
    public static final long SUITE_SEED = 7_462_910_451L;

    private SceneGenerator() {
    }

    public static SceneManifest blueprint(SceneDescriptor scene, long seed, String routeHash) {
        if (scene == null) throw new IllegalArgumentException("Scene is required");
        SceneManifest manifest = new SceneManifest();
        manifest.suiteVersion = "1";
        manifest.sceneId = scene.id();
        manifest.seed = seed;
        manifest.dimension = scene.dimension();
        manifest.anchorX = scene.anchorX();
        manifest.anchorY = scene.anchorY();
        manifest.anchorZ = scene.anchorZ();
        manifest.yaw = scene.yaw();
        manifest.pitch = scene.pitch();
        manifest.readinessRadiusChunks = scene.readinessRadiusChunks();
        manifest.cameraResource = scene.cameraResource();
        manifest.geometryRebuild = scene.geometryRebuild();
        manifest.routeHash = routeHash == null || routeHash.isBlank() ? "unavailable" : routeHash;
        manifest.contentHash = SceneContentHasher.sha256(manifest);
        return manifest;
    }
}
